<?php
$pageTitle='Sign in | HEX CHEATS SHOP';$activePage='account';require __DIR__.'/_head.php';
$messages=['not_configured'=>'Google sign-in is not configured yet. Add GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET in Railway variables.','failed'=>'Google sign-in did not complete. Please try again.','expired'=>'That sign-in link expired. Start again.','invalid'=>'Google could not verify this sign-in. Please retry.'];$googleMessage=$messages[(string)($_GET['google']??'')]??'';$next=(string)($_GET['next']??'/account');if(!str_starts_with($next,'/')||str_starts_with($next,'//')||preg_match('/[\\r\\n]/',$next)){$next='/account';}
?>
<section class="hx-panel hx-auth-panel"><p class="hx-eyebrow">YOUR HEX ACCOUNT</p><h1>Welcome back</h1><p class="hx-muted">Sign in to manage your wallet, orders and delivered keys.</p><?php if($googleMessage!==''):?><div class="hx-alert" role="status"><?=htmlspecialchars($googleMessage,ENT_QUOTES,'UTF-8')?></div><?php endif;?><a class="hx-button hx-google" href="/auth/google"><span aria-hidden="true">G</span> Continue with Google</a><div class="hx-divider"><span>or use email</span></div><form id="loginForm" class="hx-form"><label>Email<input type="email" name="email" autocomplete="email" required maxlength="254"></label><label>Password<input type="password" name="password" autocomplete="current-password" required maxlength="256"></label><button class="hx-button" type="submit">Sign in</button><div class="hx-alert" id="authStatus" role="alert"></div></form><p class="hx-muted">New here? <a href="/register">Create an account</a></p></section>
<script>document.getElementById('loginForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button'),s=document.getElementById('authStatus');s.textContent='';b.disabled=true;try{const r=await fetch('/api/store/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:f.email.value,password:f.password.value})});const d=await r.json();if(!r.ok)throw Error(d.error||'Sign in failed.');location.href=<?=json_encode($next,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>}catch(x){s.textContent=x.message||'Sign in failed.'}finally{b.disabled=false}});</script>
